const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function eeGet(obj) {
    return new Promise((resolve, reject) => obj.evaluate(resolve, reject));
  }

  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Polygon([
    [149.8, -28.7],
    [153.1, -28.7],
    [153.1, -31.9],
    [149.8, -31.9],
    [149.8, -28.7]
  ]);

  function dateAdd(d, days) {
    const dt = new Date(d + 'T00:00:00Z');
    dt.setUTCDate(dt.getUTCDate() + days);
    return dt.toISOString().slice(0, 10);
  }

  const baseStart = '2025-08-02';
  const baseEnd = '2025-08-03'; // end-exclusive
  const attempts = [
    {start: baseStart, end: baseEnd, label: 'D0'},
    {start: dateAdd(baseStart, -1), end: dateAdd(baseEnd, 1), label: 'D±1'}
  ];

  let finalTag = null;
  let printed = false;

  try {
    console.log('Region: Northern Tablelands, NSW, Australia');
    let usedDataset = null;

    // Try MODIS Terra+Aqua first, with two date windows
    for (const at of attempts) {
      const terraCol = ee.ImageCollection('MODIS/061/MOD10A1')
        .filterDate(at.start, at.end)
        .filterBounds(region);
      const aquaCol = ee.ImageCollection('MODIS/061/MYD10A1')
        .filterDate(at.start, at.end)
        .filterBounds(region);

      const terraSize = await eeGet(terraCol.size());
      const aquaSize = await eeGet(aquaCol.size());
      console.log(`MODIS Window ${at.label}: ${at.start} to ${at.end}`);
      console.log(`Terra imgs: ${terraSize}, Aqua imgs: ${aquaSize}`);

      const totalSize = (terraSize || 0) + (aquaSize || 0);
      if (totalSize === 0) {
        continue; // try next window or fallback
      }

      const col = terraCol.merge(aquaCol)
        .select('NDSI_Snow_Cover')
        .map(function(img) {
          const ndsi = img.select('NDSI_Snow_Cover');
          const valid = ndsi.gte(0).and(ndsi.lte(100));
          return ndsi.updateMask(valid);
        });

      const mergedMax = col.max().rename('NDSI_Snow_Cover');

      // Valid pixel count (unmasked)
      const validDict = await eeGet(
        mergedMax.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e9
        })
      );
      const validCount = validDict ? validDict['NDSI_Snow_Cover'] : null;

      // Snow pixel count (>0)
      const snowBinary = mergedMax.gt(0).selfMask().rename('snow');
      const snowDict = await eeGet(
        snowBinary.reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e9
        })
      );
      const snowCount = snowDict ? snowDict['snow'] : null;

      if (
        validCount === null || snowCount === null ||
        isNaN(validCount) || isNaN(snowCount)
      ) {
        console.log('MODIS reduceRegion produced null/NaN.');
        finalTag = 'C3';
        printed = true;
        break;
      }

      console.log(`Valid px: ${validCount}`);
      console.log(`Snow px: ${snowCount} (${validCount > 0 ? (100 * snowCount / validCount).toFixed(2) : '0.00'}%)`);

      if (validCount === 0) {
        console.log('No valid MODIS pixels after masking.');
        finalTag = 'C2';
        printed = true;
        break;
      }

      usedDataset = 'MODIS';
      finalTag = (snowCount > 0) ? 'A' : 'B';
      printed = true;
      break;
    }

    // Fallback to Sentinel-2 if still undecided due to empty MODIS
    if (!printed && finalTag === null) {
      // Check if MODIS was truly empty across attempts
      // We'll try S2 within ±1 day
      const s2Start = dateAdd(baseStart, -1);
      const s2End = dateAdd(baseEnd, 1);
      const s2col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(s2Start, s2End)
        .filterBounds(region);
      const s2size = await eeGet(s2col.size());
      console.log(`Sentinel-2 Window D±1: ${s2Start} to ${s2End}`);
      console.log(`S2 imgs: ${s2size}`);

      if (!s2size || s2size === 0) {
        finalTag = 'C1';
        printed = true;
      } else {
        // Mosaic SCL snow class
        const sclSnow = s2col.select('SCL').map(function(img) {
          return img.select('SCL').eq(11).rename('snow');
        }).max().rename('snow');

        // Valid pixels: where SCL is defined (count SCL across mosaic of max SCL presence)
        const sclAny = s2col.select('SCL').max().rename('SCL');

        const validDictS2 = await eeGet(
          sclAny.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: region,
            scale: 1000,
            maxPixels: 1e9
          })
        );
        const snowDictS2 = await eeGet(
          sclSnow.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: region,
            scale: 1000,
            maxPixels: 1e9
          })
        );

        const validS2 = validDictS2 ? validDictS2['SCL'] : null;
        const snowS2 = snowDictS2 ? snowDictS2['snow'] : null;

        if (
          validS2 === null || snowS2 === null ||
          isNaN(validS2) || isNaN(snowS2)
        ) {
          console.log('S2 reduceRegion produced null/NaN.');
          finalTag = 'C3';
          printed = true;
        } else if (validS2 === 0) {
          console.log('No valid S2 pixels.');
          finalTag = 'C2';
          printed = true;
        } else {
          console.log(`Valid px (S2): ${validS2}`);
          console.log(`Snow px (S2): ${snowS2} (${(100 * snowS2 / validS2).toFixed(2)}%)`);
          usedDataset = 'S2';
          finalTag = (snowS2 > 0) ? 'A' : 'B';
          printed = true;
        }
      }
    }

    if (!finalTag) {
      // If we reach here without a decision, treat as calculation failure
      finalTag = 'C3';
    }
    console.log(finalTag);
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
